/* ------------------------------------------------------------------ */
/* Optional: form + live preview + print (named export)                */
/* Usage: import { VanrangReceiptDemo } from "./VanrangReceipt";       */
/* ------------------------------------------------------------------ */
const FIELDS = [
  { id: "receiptNo", label: "Receipt No." },
  { id: "date", label: "Date", type: "date" },
  { id: "name", label: "Received from" },
  { id: "pan", label: "PAN", maxLength: 10, upper: true },
  { id: "address1", label: "Address (line 1)" },
  { id: "address2", label: "Address (line 2)" },
  { id: "mode", label: "Mode of payment", options: ["", "Cash", "UPI", "Cheque", "Bank Transfer", "Debit / Credit Card", "Online"] },
  { id: "amount", label: "Amount (₹)", type: "number" },
  { id: "txnId", label: "Transaction ID" },
];

export function VanrangReceiptDemo() {
  const [data, setData] = useState({
    receiptNo: "", date: "", name: "", pan: "", address1: "", address2: "", mode: "", amount: "", txnId: "",
  });
  const set = (id) => (e) => setData((d) => ({ ...d, [id]: e.target.value }));

  return (
    <div className="flex min-h-screen flex-wrap items-start justify-center gap-7 bg-[#e8eaee] p-7 font-['Source_Serif_4',Georgia,serif] text-[#1b2a4a] print:block print:bg-white print:p-0">
      <form autoComplete="off" className="w-[340px] rounded-[10px] border border-[#c9cfda] bg-white p-5 print:hidden">
        <h2 className="m-0 mb-3.5 text-lg font-semibold">Receipt details</h2>
        {FIELDS.map((f) => (
          <div key={f.id}>
            <label htmlFor={f.id} className="mb-1 mt-2.5 block text-[13px] font-semibold">{f.label}</label>
            {f.options ? (
              <select
                id={f.id} value={data[f.id]} onChange={set(f.id)}
                className="w-full rounded-md border border-[#c9cfda] bg-white px-2.5 py-2 text-sm focus-visible:outline focus-visible:outline-[3px] focus-visible:outline-offset-2 focus-visible:outline-[#c39a3c]"
              >
                {f.options.map((o) => <option key={o} value={o}>{o}</option>)}
              </select>
            ) : (
              <input
                id={f.id} type={f.type || "text"} maxLength={f.maxLength} value={data[f.id]} onChange={set(f.id)}
                min={f.type === "number" ? 0 : undefined} step={f.type === "number" ? "0.01" : undefined}
                className={`w-full rounded-md border border-[#c9cfda] px-2.5 py-2 text-sm focus-visible:outline focus-visible:outline-[3px] focus-visible:outline-offset-2 focus-visible:outline-[#c39a3c] ${f.upper ? "uppercase" : ""}`}
              />
            )}
          </div>
        ))}
        <button
          type="button" onClick={() => window.print()}
          className="mt-[18px] w-full cursor-pointer rounded-md border-0 bg-[#0c2246] p-[11px] text-[15px] font-semibold text-white focus-visible:outline focus-visible:outline-[3px] focus-visible:outline-offset-2 focus-visible:outline-[#c39a3c]"
        >
          Print / Save as PDF
        </button>
      </form>

      <div className="w-[min(820px,100%)] shadow-[0_6px_30px_rgba(12,34,71,0.18)] print:mx-auto print:w-[200mm] print:shadow-none">
        <VanrangReceipt {...data} />
      </div>
    </div>
  );
}